#include "model_classic.h"
#include <cmath>
#include <cstring>

// Mảng tên các phép thuật (không gộp STAND BY vào danh sách spell)
static const char* const CLASS_NAMES[7] = {
    "BOOST",
    "COPY",
    "FIREBALL",
    "P",
    "REFLECT",
    "STAND BY",
    "STOP",
};

const char* classic_get_class_name(int class_idx) {
    if (class_idx < 0) return "STAND_BY";
    if (class_idx >= 7) return "UNKNOWN";
    return CLASS_NAMES[class_idx];
}

int classic_is_standby(const float* raw_features) {
    if (!raw_features) return 1;
    // std ax,ay,az -> index 1,11,21; gx,gy,gz -> 31,41,51 (theo feature_names lúc train)
    float acc_std_sum = raw_features[1] + raw_features[11] + raw_features[21];
    float gyr_std_sum = raw_features[31] + raw_features[41] + raw_features[51];
    if (acc_std_sum < CLASSIC_STANDBY_ACC_STD_SUM && gyr_std_sum < CLASSIC_STANDBY_GYR_STD_SUM) {
        return 1; // STAND BY / Đứng yên
    }
    return 0; // Đang vung đũa
}

// Mảng màu LED RGB cấu hình cho từng phép thuật
static const uint8_t CLASS_RGB[7][3] = {
    { 170, 0, 255 },
    { 255, 0, 0 },
    { 0, 255, 0 },
    { 255, 0, 0 },
    { 255, 230, 0 },
    { 0, 0, 0 },
    { 0, 220, 255 },
};

void classic_get_class_rgb(int class_idx, uint8_t* r, uint8_t* g, uint8_t* b) {
    if (!r || !g || !b) return;
    if (class_idx < 0 || class_idx >= 7) {
        *r = 0; *g = 0; *b = 0;
        return;
    }
    *r = CLASS_RGB[class_idx][0];
    *g = CLASS_RGB[class_idx][1];
    *b = CLASS_RGB[class_idx][2];
}

